import { html, LitElement, TemplateResult } from 'lit';
import { customElement, property, query } from 'lit/decorators.js';
import '@awesome.me/webawesome/dist/components/radio/radio.js';
import '@awesome.me/webawesome/dist/components/radio-group/radio-group.js';
import '@awesome.me/webawesome/dist/components/input/input.js';

@customElement('lexml-ui-data')
export class Data extends LitElement {
  @query('#input-data')
  inputData!: HTMLInputElement;

  @query('#data-component')
  private group!: HTMLElement & { value: string };

  @query('#no-date')
  optionNaoInformarData!: any;

  @property({ type: String })
  data = new Date().toISOString().slice(0, 10);

  firstUpdated(): void {
    setTimeout(() => {
      const internalLabel = this.inputData.shadowRoot?.querySelector('label');

      if (internalLabel) {
        internalLabel.addEventListener('click', () => {
          this.selecionarRadioData();
        });
      } else {
        console.error('FALHA: A label interna do wa-input.');
      }
    }, 100);
  }

  private selecionarRadioData(): void {
    const radio = this.shadowRoot?.querySelector(
      '#radio-data-option',
    ) as HTMLInputElement | null;

    if (radio && !radio.checked) {
      radio.checked = true;
      this.setDate();
    }
  }
  updated(): void {
    this.inputData.value =
      this.data ||
      this.inputData.value ||
      new Date().toISOString().replace(/T.+$/, '');
    if (!this.data && !this.optionNaoInformarData.checked) {
      this.optionNaoInformarData.checked = true;
    }
  }

  render(): TemplateResult {
    return html`
      <style>
        :host {
          font-size: 14px;
          --wa-font-size-medium: 14px;
          font-family: 'Helvetica Neue', 'Helvetica', 'Arial', sans-serif;
        }
        fieldset.lexml-data {
          background-color: var(--wa-color-gray-95);
          box-shadow: var(--wa-shadow-m);
          padding: 20px;
          border: solid var(--wa-panel-border-width) var(--wa-color-gray-90);
          border-radius: var(--wa-border-radius-s);
          max-width: 655px;
          margin: 0;
        }
        legend {
          background-color: var(--wa-color-gray-90);
          font-weight: bold;
          border-radius: 6px;
          border: 1px solid var(--wa-color-gray-85);
          padding: 2px 8px;
          box-shadow: var(--wa-shadow-s);
          color: #333;
          margin-left: 8px;
        }

        wa-radio-group {
          margin-left: 10px;
        }
        wa-radio {
          font-size: 14px;
        }
        wa-input {
          max-width: 190px;
        }
        .label-on-left {
          display: grid;
          grid-template-columns: 32px 1fr;

          wa-input {
            grid-column: 1 / -1;
            grid-row-end: span 2;
            display: grid;
            grid-template-columns: subgrid;
            gap: 0 var(--wa-space-l);
            margin-right: 20px;
            font-size: 14px;
          }
          ::part(input) {
            margin-top: -10px;
          }
          ::part(label) {
            text-align: right;
          }

          ::part(hint) {
            grid-column: 2;
          }
        }
        .fiel-click-radio {
          margin-top: -10px;
        }
        .label-on-left wa-input::part(label) {
          cursor: pointer;
        }
        @media (max-width: 480px) {
        }
      </style>
      <fieldset class="lexml-data">
        <legend>Data</legend>
        <wa-radio-group
          id="data-component"
          orientation="horizontal"
          size="medium"
          .value=${this.data ? '2' : '1'}
        >
          <wa-radio
            id="radio-data-option"
            name="data"
            value="2"
            @click=${this.setDate}
          >
            <div class="label-on-left">
              <wa-input
                id="input-data"
                label="Data"
                type="date"
                ?disabled=${!this.data}
                @input=${this.setDate}
              >
              </wa-input>
            </div>
          </wa-radio>
          <wa-radio name="data" id="no-date" value="1" @click=${this.resetDate}>
            Não informar
          </wa-radio>
        </wa-radio-group>
      </fieldset>
    `;
  }

  private resetDate(): void {
    const original = this.data;
    this.data = '';
    if (original !== this.data) {
      this.agendarEmissaoEventoOnChange();
    }
  }

  private setDate(): void {
    if (this.inputData) {
      const original = this.data;
      this.data = this.inputData.value;
      if (original !== this.data) {
        this.agendarEmissaoEventoOnChange();
      }
    }
  }

  private timerOnChange = 0;
  private agendarEmissaoEventoOnChange(): void {
    clearTimeout(this.timerOnChange);
    this.timerOnChange = window.setTimeout(
      () => this.emitirEventoOnChange(),
      1000,
    );
  }

  private emitirEventoOnChange(): void {
    this.dispatchEvent(
      new CustomEvent('onchange', {
        bubbles: true,
        composed: true,
        detail: {
          origemEvento: 'data',
        },
      }),
    );
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'lexml-ui-data': Data;
  }
}
